import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../tests/utils";
import type { Skill, SkillCatalog, SkillState } from "../types";
import { MiddlePane } from "./MiddlePane";

// The flow canvas pulls in the full ReactFlow tree; the fork is what's under
// test, so a marker stands in for it (same pattern as FlowSection.test.tsx).
vi.mock("./FlowSection", () => ({
  FlowSection: () => <div data-testid="flow-section" />,
}));

const cardReplace: Skill = {
  id: "card_replace",
  name: "Card Replace",
  description: "Order a replacement card.",
  is_default: false,
  engine_managed: false,
  disabled: false,
  sections: [
    {
      type: "prose",
      segments: [{ text: "Help the customer with lock_card when needed.", condition: null }],
    },
  ],
  blocks: {
    main: {
      ordered_block_id: "card_replace__main",
      complete_when: null,
      steps: [{ id: "start", kind: "action" }],
    },
  },
  referenced_skills: [],
  tool_names: ["lock_card"],
  hidden: false,
};

const skillCatalog: SkillCatalog = { card_replace: cardReplace };

const skillState: SkillState = {
  active_skill: {
    skill_id: "card_replace",
    ordered_block_id: "card_replace__main",
    step_id: "start",
  },
  blocks: { card_replace__main: { status: "active" } },
  evaluated_conditions: {},
  tools: {},
  llm_calls: [],
  memory: {},
};

describe("MiddlePane", () => {
  it("renders SkillSection in skill mode and FlowSection otherwise", () => {
    const { unmount } = renderWithProviders(<MiddlePane />, {
      initialStoreState: { engineType: "mantle", skillCatalog, skillState },
    });
    expect(screen.getByTestId("skill-section")).toBeInTheDocument();
    expect(screen.queryByTestId("flow-section")).not.toBeInTheDocument();
    unmount();

    renderWithProviders(<MiddlePane />, {
      initialStoreState: { engineType: "calm", skillCatalog: null },
    });
    expect(screen.getByTestId("flow-section")).toBeInTheDocument();
    expect(screen.queryByTestId("skill-section")).not.toBeInTheDocument();
  });
});
